import{_ as e,c as a,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const p=JSON.parse('{"title":"Yield Planner","description":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield.","frontmatter":{"title":"Yield Planner","description":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield.","head":[["meta",{"name":"description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["meta",{"property":"og:title","content":"Yield Planner"}],["meta",{"property":"og:description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/yield-planner.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Yield Planner"}],["meta",{"name":"twitter:description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/yield-planner.html"}]]},"headers":[],"relativePath":"guides/yield-planner.md","filePath":"guides/yield-planner.md"}'),l={name:"guides/yield-planner.md"};function n(o,t,s,d,h,c){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="yield-planner" tabindex="-1">Yield Planner <a class="header-anchor" href="#yield-planner" aria-label="Permalink to “Yield Planner”">​</a></h1><p>The Yield Planner is your batch reality check. Give it total dough weight, pick a mode, and it tells you either <strong>how many pieces</strong> or <strong>how heavy each piece</strong> should be. No guesswork, no napkin math.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><ol><li>Open <strong>Summary</strong> and click <strong>Yield planner</strong>, then <strong>Open</strong>.</li><li>Choose a mode: <strong>By Number of Pieces</strong> or <strong>By Grams per Piece</strong>.</li><li>Enter one value and the planner does the rest, instantly.</li></ol><h2 id="use-the-actual-final-weight-optional" tabindex="-1">Use the Actual Final Weight (Optional) <a class="header-anchor" href="#use-the-actual-final-weight-optional" aria-label="Permalink to “Use the Actual Final Weight (Optional)”">​</a></h2><p>If your dough loses weight during mixing, resting, or benching, check <strong>Use actual final weight</strong> and enter the weighed total in grams. The planner swaps in that real-world number so your yield stays honest.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Dough weight is the input; pieces are the output. The tool never &quot;makes&quot; dough - it just divides what you already have.</p></div><h2 id="common-starting-weights" tabindex="-1">Common Starting Weights <a class="header-anchor" href="#common-starting-weights" aria-label="Permalink to “Common Starting Weights”">​</a></h2><p>These are solid starting points. Adjust for dough type, hydration, and the finished size you want.</p><table tabindex="0"><thead><tr><th>Item</th><th>Starter weight (g)</th><th>Typical range (g)</th><th>Notes</th></tr></thead><tbody><tr><td>Tortilla (10-12 in, rolled thin)</td><td>47</td><td>40-55</td><td>47g yields a thin 10-12 inch tortilla.</td></tr><tr><td>Dinner roll</td><td>60</td><td>50-80</td><td>Soft dinner rolls, medium size.</td></tr><tr><td>Sandwich roll</td><td>100</td><td>85-120</td><td>For buns or sandwich rolls.</td></tr><tr><td>Hoagie / sub roll</td><td>160</td><td>140-190</td><td>Classic 6-8 inch subs.</td></tr><tr><td>1 lb loaf pan</td><td>454</td><td>430-500</td><td>Starting dough weight for a 1 lb pan.</td></tr><tr><td>1.5 lb loaf pan</td><td>680</td><td>640-760</td><td>Starting dough weight for a 1.5 lb pan.</td></tr><tr><td>2 lb loaf pan</td><td>908</td><td>850-1000</td><td>Starting dough weight for a 2 lb pan.</td></tr></tbody></table><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><h2 id="example-plan-tortillas" tabindex="-1">Example: Plan Tortillas <a class="header-anchor" href="#example-plan-tortillas" aria-label="Permalink to “Example: Plan Tortillas”">​</a></h2><ul><li>Flour: <strong>450 g</strong></li><li>Final dough: <strong>~860 g</strong></li><li>Target weight: <strong>47 g</strong></li><li>Result: <strong>18 pieces</strong></li></ul><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Weigh your dough for the most accurate yield count.</li><li>Stiffer doughs feel tighter in smaller pieces; softer doughs can handle slightly larger pieces.</li><li>If you tweak hydration, re-check piece size after a short rest.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/recipes/tortillas.html">No-knead Tortillas</a></li></ul><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',18)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
